def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    output = [row[:] for row in grid]

    # Process each connected region
    visited = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            # Flood fill to get all cells of this color connected by 4-connections
            color = grid[r][c]
            region = []
            stack = [(r, c)]
            visited[r][c] = True

            while stack:
                rr, cc = stack.pop()
                region.append((rr, cc))

                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nn, nn_col = rr + dr, cc + dc
                    if 0 <= nn < rows and 0 <= nn_col < cols:
                        if not visited[nn][nn_col] and grid[nn][nn_col] == color:
                            visited[nn][nn_col] = True
                            stack.append((nn, nn_col))

            if len(region) < 9:  # Need at least 3x3
                continue

            # Get bounding box
            min_r = min(x[0] for x in region)
            max_r = max(x[0] for x in region)
            min_c = min(x[1] for x in region)
            max_c = max(x[1] for x in region)

            h = max_r - min_r + 1
            w = max_c - min_c + 1

            # Fill interior (exclude borders)
            for rr in range(min_r + 1, max_r):
                for cc in range(min_c + 1, max_c):
                    output[rr][cc] = 2

            # Add patterns based on aspect ratio
            if h == 3 and w == 3:
                # Cross pattern
                for cc in range(min_c, max_c + 1):
                    output[min_r + 1][cc] = 2
                for rr in range(min_r, max_r + 1):
                    output[rr][min_c + 1] = 2
            elif h > w:
                # Tall: vertical center line (all rows, just that col)
                center_col = min_c + w // 2
                for rr in range(min_r, max_r + 1):
                    output[rr][center_col] = 2
            elif w > h:
                # Wide: horizontal center line (all cols, just that row)
                center_row = min_r + h // 2
                for cc in range(min_c, max_c + 1):
                    output[center_row][cc] = 2

    return output
